(ns app.icons)

(defn icon*
  ([svg]
   (icon* svg nil))
  ([svg {:keys [class] :or {class ""} :as opts}]
   (-> svg
       (update-in [1] #(merge % (dissoc opts :class)))
       (update-in [1 :class]
                  (fn [existing new]
                    (str new " " existing)) (str  "icon " class)))))

(defn deficon [svg] (partial icon* svg))

